import { existsSync, readFileSync } from "node:fs";
import * as ort from "onnxruntime-web/wasm";
import { describe, expect, it } from "vitest";
import { createRedactor } from "../src/redactor";
import type { Size, Variant } from "../src/models";
import type { EngineName } from "../src/engines/engine";

// End-to-end parity with the Python evaluator on the same ONNX files, for both engines. Fixtures are generated by
// training/scripts/js_fixtures.py from validation text and are not published; the tests skip without them.
// PII_ENGINES=builtin (or onnxruntime) runs one; PII_SIZES=nano,medium limits the sizes.
const FIX = new URL("./fixtures/", import.meta.url).pathname;
const MODELS = process.env.PII_MODELS ?? new URL("./models/", import.meta.url).pathname;
const localFetch = (async (url: string) => new Response(readFileSync(url.replace("file://", "")))) as unknown as typeof fetch;

// in Node, hand onnxruntime its wasm binary directly (it would otherwise fetch() a file URL)
ort.env.wasm.wasmBinary = readFileSync(new URL("../node_modules/onnxruntime-web/dist/ort-wasm-simd-threaded.wasm", import.meta.url));
ort.env.wasm.numThreads = 1;

const ENGINES = (process.env.PII_ENGINES ?? "builtin,onnxruntime").split(",") as EngineName[];
const SIZES = process.env.PII_SIZES?.split(",");
const RUNS: [Size, Variant, number][] = [
  ["large", "q4e", 0], ["large", "q4", 0], ["medium", "q4e", 0], ["medium", "q4", 0],
  ["small", "q4", 0], ["small", "q4e", 0], ["nano", "q4", 0], ["nano", "q4e", 0],
  ["medium", "q4e", -0.5], ["nano", "q4", 1],
];

for (const engine of ENGINES)
for (const [size, variant, bias] of RUNS.filter(([s]) => !SIZES || SIZES.includes(s))) {
  const file = `${FIX}/predict-${size}-${variant}${bias ? `-b${bias}` : ""}.jsonl`;
  const model = `${MODELS}/pii-${size}/onnx/model_${variant}.onnx`;
  describe.skipIf(!existsSync(file) || !existsSync(model))(`${engine} model spans ${size} ${variant} bias ${bias}`, () => {
    it("match the Python evaluator", async () => {
      const rows = readFileSync(file, "utf8").trim().split("\n").map((l) => JSON.parse(l));
      // Python O bias b is added to the O logit; sensitivity = −b
      const r = await createRedactor({ engine, size, variant, modelUrl: `file://${MODELS}/pii-${size}/`, fetch: localFetch, cache: false, regex: false, sensitivity: -bias });
      let same = 0;
      const diffs: string[] = [];
      for (const row of rows) {
        const units: number[] = [0];
        for (const ch of row.text as string) units.push(units[units.length - 1] + ch.length);
        const want = row.spans.map((s: any) => `${units[s.start]}-${units[s.end]}:${s.label}`).join(" ");
        const got = (await r.detect(row.text)).map((s) => `${s.start}-${s.end}:${s.label}`).join(" ");
        if (want === got) same++;
        else if (diffs.length < 3) diffs.push(`${JSON.stringify(row.text).slice(0, 60)}\n  py ${want}\n  js ${got}`);
      }
      await r.dispose();
      if (diffs.length) console.log(`${engine} ${size} ${variant}: ${same}/${rows.length}\n${diffs.join("\n")}`);
      expect(same / rows.length).toBeGreaterThanOrEqual(0.99);
    }, 600_000);
  });
}
